CREATE TABLE users (id UUID PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(180) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'GUEST');
CREATE TABLE bookings (id UUID PRIMARY KEY, reference VARCHAR(30) UNIQUE NOT NULL, guest_id UUID REFERENCES users(id), check_in DATE NOT NULL, check_out DATE NOT NULL, guests INTEGER NOT NULL, total_amount NUMERIC(10,2), status VARCHAR(20) NOT NULL DEFAULT 'PENDING');
CREATE TABLE enquiries (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL, message VARCHAR(2000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
